def distance(g, depart, arrivee):
    file = deque([(depart, 0)])
    vus = {depart}
    while file:
        n, d = file.popleft()
        if n == arrivee:
            return d
        for v in g[n]:
            if v not in vus:
                vus.add(v)
                file.append((v, d + 1))
    return -1

