def dijkstra(g, s):
    dist = {s: 0}
    tas = [(0, s)]
    while tas:
        d, u = heapq.heappop(tas)
        if d > dist[u]:
            continue         # entrée périmée
        for v, w in g[u]:
            if d + w < dist.get(v, float("inf")):
                dist[v] = d + w
                heapq.heappush(tas, (d + w, v))
    return dist

